 "content": "from collections import deque


def transform(grid):
    """Fill closed cavities with 7 when cavity height is odd, else 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                cr, cc = q.popleft()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and not seen[nr][nc]
                            and grid[nr][nc] == color):
                        seen[nr][nc] = True
                        q.append((nr, nc))
            r0 = min(x for x, _ in component)
            r1 = max(x for x, _ in component)
            c0 = min(y for _, y in component)
            c1 = max(y for _, y in component)
            ih, iw = r1 - r0 - 1, c1 - c0 - 1
            if ih <= 0 or iw <= 0:
                continue
            # Only complete rectangular outlines are fillable objects.
            if not all(grid[r0][cc] == color and grid[r1][cc] == color for cc in range(c0, c1 + 1)):
                continue
            if not all(grid[rr][c0] == color and grid[rr][c1] == color for rr in range(r0, r1 + 1)):
                continue
            fill = 7 if ih % 2 or iw % 2 else 2
            for rr in range(r0 + 1, r1):
                for cc in range(c0 + 1, c1):
                    out[rr][cc] = fill
    return out


